"""Correções preparadas; não escreve no Anki."""
import json,re
from pathlib import Path
C=Path(__file__).parent;N={n['noteId']:n for n in json.load(open(C/'notas-antes.json'))};P={}
def set_(nid,text=None,extra=None,reason='',image=None,keep_images=True):
 old={k:v['value'] for k,v in N[nid]['fields'].items()};f={}
 if text is not None:f['Text']=text
 if extra is not None:
  imgs=re.findall(r'<img\b[^>]*>',old.get('Extra','')) if keep_images else []
  imgs=list(dict.fromkeys(imgs));f['Extra']=extra+(' <br><br>'+''.join(imgs) if imgs else '')
 if image:
  s=f.get('Extra',old.get('Extra',''));s=re.sub(r'<img\b[^>]*>','',s) if not keep_images else s
  f['Extra']=s+'<br><br><img src="'+image+'" style="width:100%;max-width:950px;height:auto;display:block;margin:18px auto">'
 P[str(nid)]={'fields':f,'motivo':reason,'antes':old,'suspender':False}
set_(1790981518578,extra='Left gastric vein drains to the portal system. Esophageal veins communicate with the azygos system, which drains into the superior vena cava. Portal hypertension can reverse flow through this junction and dilate esophageal veins.',reason='O verso confundia cava superior com inferior; a figura será focada na junção esofágica.')
set_(1790981519924,'<b>Intestinal lymph carrying chylomicrons</b> enters the left venous angle through the {{c1::thoracic duct}}.',extra='Lacteals drain through intestinal lymphatics and the cisterna chyli into the thoracic duct. It empties at the junction of the left internal jugular and subclavian veins.',reason='Lymph isoladamente admitia múltiplas respostas. Origem intestinal e desembocadura venosa tornam o alvo único.')
set_(1790999836655,'<b>GI hormones released by digestive signals</b><br><b>Antral peptides and stomach distension</b> → {{c1::gastrin}}<br><b>Acid entering the duodenum</b> → {{c1::secretin}}<br><b>Duodenal fat and amino acids</b> → {{c2::cholecystokinin (CCK)}}',extra='G cells release gastrin, which promotes gastric acid secretion. Duodenal S cells release secretin to promote bicarbonate secretion; I cells release CCK to promote pancreatic enzymes and gallbladder contraction.',reason='A pista distingue estímulo, célula e função sem esconder adjetivo genérico nem induzir pela inicial.')
set_(1791000312550,extra='Ferritin encloses iron in a protein shell, limiting the free iron available for radical-generating reactions. In enterocytes, iron kept in ferritin can leave the body when the cell is shed.',reason='O verso passa a explicar proteção química e perda intestinal, em vez de repetir armazenamento.')
set_(1791557941758,extra='The polysaccharide capsule makes engulfment less efficient and helps Cryptococcus survive host defenses. India ink outlines an unstained halo around the yeast; mucicarmine stains the capsule.',image='nebli-0511-mb50-p143.png',keep_images=False,reason='Incluída figura real de nanquim da aula que demonstra precisamente a cápsula antifagocítica.')
set_(1791626776253,extra='Dermatophytes invade keratinized skin, hair and nails. Epidermophyton usually spares hair; Microsporum nail infection is very uncommon. This is a tissue-tropism comparison, not a claim that all fungi infect these three sites.',reason='Preservados os índices editados por Davi; comentário explica o eixo e a exceção sem refazer a tabela aprovada.')
set_(1791626778904,extra='Distal-lateral nail involvement is typical of dermatophyte onychomycosis. Candida often involves the proximal nail fold with paronychia; this contrast is a usual pattern, not an absolute diagnostic rule.',image='nebli-0511-mb50-p117.png',keep_images=False,reason='Comparação fotográfica da aula mostra os dois padrões ungueais descritos.')
set_(1791627546928,'A <b>eukaryotic gene</b> integrates inputs from <b>multiple transcription factors</b> through {{c1::combinatorial control}}.',extra='The combination of activators, repressors and accessible regulatory sites determines when a gene is expressed. Reusing factors in different combinations creates cell-specific expression patterns.',reason='Dozens era número vago; o alvo duradouro é o princípio de controle combinatório.')
set_(1791627547475,image='nebli-0511-bm46-p17.png',keep_images=False,reason='Substituída ausência de figura por mecanismo real com Mediator entre ativador e maquinaria Pol II.')
set_(1791627549152,image='nebli-0511-bm46-p21.png',keep_images=False,reason='Figura real de Gal4 separa fisicamente domínio de ligação e domínio de ativação; sai o esquema textual genérico.')
set_(1791627549276,'<b>DNA-bound Gal4</b> activates transcription by <b>recruiting</b> {{c1::coactivators}} that modify chromatin or connect to the basal machinery.',extra='Gal4 does not perform all downstream tasks itself. Its activation domain recruits proteins such as Mediator and chromatin modifiers, linking sequence recognition to transcription initiation.',reason='Negrito situa quem age e a ação visível; o comentário explica recrutamento em vez de repetir a frase.')
set_(1791627549652,'A <b>LexA–Gal4 hybrid</b> binds a LexA DNA site, while the <b>Gal4 segment</b> supplies its {{c1::activation domain}}.',extra='DNA binding and activation are separable protein functions. Replacing the DNA-binding domain changes which site the hybrid recognizes without removing the Gal4 activation function.',reason='A recuperação distingue modularidade das duas funções; o verso explica o resultado experimental.')
set_(1791627550877,extra='Ligand binding brings receptor-associated JAKs together. Phosphorylated STAT proteins dimerize, enter the nucleus and regulate transcription, connecting an extracellular cytokine signal to gene expression.',image='nebli-0511-bm46-p36.png',keep_images=False,reason='A figura da aula acompanha receptor, JAK, STAT e núcleo na mesma sequência descrita.')
set_(1791628674574,'<b>Sporothrix</b> appears as a <b>cigar-shaped budding cell in tissue</b>, the {{c1::yeast}} form, and grows as {{c1::mold}} in environmental culture.',extra='Sporothrix is thermally dimorphic. Tissue yeast and filamentous culture are different forms of the same fungus; S. brasiliensis is important in zoonotic transmission in Brazil.',reason='Retiradas alternativa binária e duplicação de artigo; a imagem de levedura é identificada sem fingir que mostra bolor.')
set_(1791628675198,extra='Traumatic implantation produces a chronic granulomatous lesion. Pigmented muriform cells in tissue distinguish chromoblastomycosis from phaeohyphomycosis, in which pigmented hyphae remain visible.',reason='Encurtado o verso mantendo causa e contraste morfológico, retirando repetição clínica.')
set_(1791629593971,extra='The follicle is the B-cell region, next to the T-cell zone. Activated T and B cells first meet at this border; germinal-center formation occurs later inside the follicle.',reason='Verso distingue encontro inicial de centro germinativo sem uma definição longa paralela.')
set_(1791630172920,'In <b>bacterial mRNA</b>, a <b>metabolite-binding RNA structure</b> that directly changes gene expression is a {{c1::riboswitch}}.',extra='The RNA itself binds the ligand; no separate sensory protein is required. In the SAM example, ligand-induced folding hides the ribosome-binding site and reduces translation.',reason='O alvo agora é induzido pela ligação direta de metabólito ao RNA e a figura mostra o RBS ocultado.')
set_(1791630173546,extra='The repressor limits transcription initiation at the operator. Attenuation instead senses translation of the leader peptide and determines whether an RNA terminator forms before the structural genes.',image='nebli-0511-bm54-p9.png',keep_images=False,reason='Verso e figura distinguem dois níveis de controle, sem sugerir que repressor e atenuação sejam o mesmo mecanismo.')
set_(1791630173671,extra='With abundant charged tRNA-Trp, the ribosome translates the leader without stalling and covers region 2. Regions 3 and 4 then pair into the transcription terminator.',image='nebli-0511-bm54-p9.png',keep_images=False,reason='A legenda causal explica por que Trp alto permite a alça 3:4 mostrada na aula.')
set_(1791630173920,'In <b>trp attenuation with scarce tryptophan</b>, the <b>stalled leader ribosome</b> permits an {{c1::antiterminator}} hairpin to form.',extra='Stalling at the leader Trp codons leaves region 2 available to pair with region 3. This 2:3 antiterminator prevents 3:4 pairing, allowing transcription of the structural genes.',reason='Duas frentes cobravam Trp alto e terminador; esta passa a cobrar a condição oposta por mecanismo, preservando ID e histórico.')
set_(1791630175095,extra='Nonhomologous end joining repairs the break without a homologous donor template. End processing can produce indels; only some repair products disrupt gene function. An indel outside a coding frame or divisible by three need not cause a frameshift.',reason='Removidas garantias falsas de frameshift/knockout e de reparo preciso por nickase pareada.')
set_(1791630176396,extra='Long double-stranded RNA can yield siRNAs, while miRNAs arise from genome-encoded hairpin precursors. Dicer processes many such precursors; a guide strand loaded into Argonaute directs silencing by sequence complementarity.',image='nebli-bm54-sirna-via-p22-20261025.jpeg',keep_images=False,reason='O verso explica origem versus maquinaria compartilhada; conferir figura real de RNAi antes de aplicar.')
set_(1791630176520,extra='lin-4 produces a small regulatory RNA rather than a protein. It pairs with sites in the lin-14 mRNA 3′ UTR and reduces LIN-14 expression, helping time larval developmental transitions.',image='nebli-0511-bm54-p29.png',keep_images=False,reason='O exemplo histórico agora ensina o mecanismo e usa a figura real dos sítios de pareamento lin-4/lin-14.')
set_(1791630179395,'Cytoplasmic granules enriched in <b>mRNA-decapping and decay proteins</b> are called {{c1::P-bodies}}.',extra='Processing bodies contain untranslated mRNAs and proteins involved in repression and turnover, including decapping factors. Visible P-body formation is not required for every mRNA-decay event.',image='nebli-0511-bm54-p76.png',keep_images=False,reason='Alvo encurtado ao nome técnico; retirado pressuposto de que todo controle de qualidade ocorre ali.')
set_(1791630904467,extra='Multiple buds radiate from a mother yeast, producing the pilot’s-wheel pattern. Compare tissue forms below: Histoplasma is small and intracellular, Blastomyces buds broadly, and Coccidioides forms spherules.',keep_images=False,reason='Duas figuras com funções distintas substituem três fotos repetidas: foco em Paracoccidioides e comparador pedido.')
P[str(1791630904467)]['fields']['Extra']+='<br><br><img src="ad330188b77ba49cc3525118aad88bdc.jpg" style="width:100%;max-width:600px;height:auto"><br><br><img src="b39abbbf00aa0b03a99911510c118e8c.webp" style="width:100%;max-width:950px;height:auto">'
set_(1791630905518,extra='Disturbing soil enriched with bat or bird droppings releases airborne microconidia, which reach the lungs when inhaled. Cave and roost exposure are environmental risks; the usual transmission is not a bat bite.',reason='Mantida a cadeia ambiente→aerossol→pulmão e retirado contraste lateral desnecessário.')
set_(1791630906367,extra='Oral lesions in disseminated infection may ulcerate on the tongue or palate. These are manifestations of dissemination, not the usual portal of entry.',image='nebli-0511-mb50-p32.png',keep_images=False,reason='Figura da própria aula localiza língua e palato; comentário separa lesão disseminada de via de entrada.')
set_(1791630906668,'Fungal {{c1::culture}} can confirm <b>histoplasmosis</b> when <b>direct examination is insensitive</b>.',extra='Small intracellular yeasts can be missed on direct examination. Culture demonstrates the organism but may take weeks; antigen detection and histopathology provide other diagnostic evidence.',reason='Retirado relies absoluto; foto de leveduras intracelulares permanece como explicação da dificuldade, não imagem de cultura.')
set_(1791631345113,image='nebli-0511-bm52-p29.png',keep_images=False,reason='A figura real separa remodelador de cromatina e HAT e mostra recrutamento por ativadores.')
set_(1791631347092,extra='DNMT1 preferentially methylates the unmethylated strand at hemimethylated CpG sites after replication. This copies a DNA-methylation pattern; histone reader–writer systems instead act on histone marks.',image='nebli-0511-bm52-p45.png',keep_images=False,reason='Retirada imagem duplicada e comparação longa; mantidos substrato, momento e mecanismo.')
set_(1791631347892,'In <b>iPS-cell reprogramming</b>, the growth-promoting factor <b>c-Myc</b> raises concern because it is an {{c1::oncogene}}.',extra='Reprogramming must change cell identity without leaving uncontrolled proliferation. c-Myc increases growth-related transcription; integrating vectors add insertional risk, whereas non-integrating and factor-reduced methods avoid some of these risks.',reason='Sai generalização de que todos os fatores/protocolos são igualmente oncogênicos; entra consequência causal da proliferação.')
set_(1791780353397,extra='Major basic protein is a cationic eosinophil-granule protein that damages membranes. Release onto helminths helps injure parasites, but release onto airway epithelium can also harm host tissue in asthma.',reason='Conectados alvo parasitário e dano colateral pelo mesmo mecanismo de membrana.')
set_(1792065183130,'<b>Endemic systemic dimorphic fungi</b> usually initiate infection when <b>airborne environmental propagules</b> enter through {{c1::inhalation}}.',extra='Environmental growth supplies inhaled propagules that establish an initial pulmonary infection. Dissemination and tissue morphology depend on the fungus and host; this is not a rule for every geographically endemic fungal skin disease.',reason='Circunscrito o universo sistêmico dimórfico para não universalizar micose endêmica de pele.')
set_(1792082060961,'Phosphorylation of the <b>RNA polymerase II</b> {{c1::CTD}} promotes <b>promoter escape and elongation</b>.',extra='CTD means C-terminal domain of the largest Pol II subunit. Its phosphorylation changes protein interactions, helping Pol II leave the initiation complex and recruit RNA-processing factors during elongation.',reason='Tail era palavra genérica; o alvo passa a ser CTD, com expansão e consequência funcional no verso.')
set_(1792328914296,'<b>Spinal cord segments</b><br><b>Sympathetic lateral horn</b>: {{c1::T1–L2}}<br><b>Cervical enlargement</b>: {{c2::C5–T1}}<br><b>Lumbosacral enlargement</b>: {{c2::L2–S2}}',reason='Negrito em cada critério de comparação, não somente no título; sem confundir nível medular com vértebra.')
set_(1792487516279,extra='A productive μ chain forms the pre-BCR with a surrogate light chain; conventional light-chain rearrangement then produces surface IgM. Mature naive B cells coexpress IgM and IgD by alternative RNA processing. Plasma and memory cells are alternative antigen-experienced fates, not obligatory steps in one linear sequence.',reason='Preservada organização editada por Davi; retiradas repetições sem apagar o mecanismo e a bifurcação de destinos.')
set_(1792695022241,'<b>Viral early/late gene programs</b><br><b>Before genome replication</b>: early {{c1::polymerase::p…}} expression supplies copying enzymes.<br><b>After genome replication</b>: late {{c1::capsid::c…}} proteins package the progeny genomes.',extra='This timing separates preparation for genome replication from particle assembly. The details vary among virus families; RNA viruses do not all express every gene simultaneously.',reason='Negrito destaca ordem e função; retirado absoluto incorreto sobre todos os vírus RNA.')
set_(1792695033836,'<b>(+)RNA viruses that express a polyprotein</b><br><b>Genome translation</b> produces a {{c1::polyprotein::p…}}.<br><b>Cleavage by viral</b> {{c1::protease::p…}} frees functional proteins.<br><b>Genome copying</b> uses a {{c1::negative::n…}} RNA intermediate.',extra='The positive-sense genome can serve as mRNA. Processing releases replication proteins; the negative-sense intermediate then templates new positive-sense genomes. Other positive-sense RNA viruses also use subgenomic RNAs or additional expression strategies.',reason='Limitada a afirmação ao grupo que expressa poliproteína; eixo único tradução→processamento→cópia.')
set_(1792695036313,'<b>Retroviral gene expression</b><br><b>Reverse transcription</b> starts from a host {{c1::tRNA}} primer.<br><b>After integration</b>, host {{c1::RNA polymerase II}} transcribes the provirus.',reason='Destaque nos momentos que discriminam primer da transcrição posterior, mantendo índices e figura real.')
set_(1792695055945,extra='Budding wraps viral components in a host lipid bilayer containing viral glycoproteins. The donor membrane depends on the virus. Herpesviruses undergo nuclear-envelope transit and later secondary envelopment at cytoplasmic membranes; the final envelope is not simply retained from the nuclear membrane.',image='nebli-0511-mb58-p88.png',keep_images=False,reason='Corrigida origem final de envelope herpético e removido falso impedimento de acúmulo intracelular; figura mostra brotamento.')
set_(1792696993158,'O <b>tronco encefálico</b> tem seu <b>limite inferior</b> no plano do {{c1::forame magno}} e continua superiormente com o {{c2::diencéfalo}}.',extra='The brainstem comprises medulla, pons and midbrain. It continues caudally as the spinal cord at the foramen magnum and rostrally toward the diencephalon.',reason='Negrito explicita região e eixo inferior/superior; verso em inglês conforme plano UC07.')
set_(1792713398630,extra='The stomach lies anterior to the pancreas across the lesser sac. The pancreatic head fits within the duodenal loop, while the tail approaches the splenic hilum. The figure is an exposed posterior abdominal wall after anterior structures have been removed.',reason='A figura exposta não mostra estômago; necessário substituir por relação sagital antes de fechar imagem.')
set_(1792713401129,extra='Most of the pancreas becomes fixed against the posterior abdominal wall during development. The tail reaches the splenic hilum within the splenorenal ligament, the important peritoneal exception.',reason='Retirada função exócrina/endócrina que não ajudava o alvo peritoneal; procurar figura que mostre o peritônio.')
set_(1792713405053,'<b>Entre as refeições</b>, a maior resistência do <b>esfíncter da via biliar distal</b> favorece o desvio da bile pelo {{c1::ducto cístico}} para a vesícula.',extra='A patent cystic duct permits bile to enter the gallbladder when resistance to duodenal flow is higher. During a meal, gallbladder contraction and sphincter relaxation favor flow into the duodenum.',reason='Distinguido esfíncter distal de contração vesicular; a figura anterior só mostrava ampola, não o desvio cístico.')
set_(1792713410206,'Na <b>hipertensão portal</b>, {{c2::varizes gástricas}} podem envolver <b>anastomoses no fundo gástrico</b> entre {{c1::veias gástricas curtas}} e a veia {{c1::frênica inferior}}.',extra='Short gastric veins drain the fundus into the splenic vein and portal system. Inferior phrenic veins provide systemic connections; drainage patterns vary, and gastric varices may also have gastrorenal shunts. Splenic vein obstruction can produce isolated gastric varices.',reason='Destaque fora das lacunas nos critérios anatômico e hemodinâmico; não esconde apenas adjetivo secundário.')
set_(1792713410554,'Na <b>hipertensão portal</b>, as veias {{c1::paraumbilicais}} comunicam-se com as {{c1::epigástricas superficiais}}, produzindo <b>veias dilatadas ao redor do umbigo</b>, a cabeça de medusa.',reason='Negrito distribuído na causa e achado visível; preservados os dois vasos como alvo.')
set_(1792753604544,extra='Infection at different airway levels produces different syndromes, from rhinitis to pneumonia. Lower-airway disease can impair gas exchange, but severity also depends on viral properties and host responses.',reason='Removida regra falsa de gravidade exclusivamente proporcional à profundidade; figura real permanece alinhada ao sítio.')
set_(1792753611264,'In <b>resting memory B cells</b>, <b>EBV latency</b> with no viral protein expression is type {{c1::0}}.',extra='Without viral protein production, infected resting cells avoid recognition by T cells directed against those viral antigens. Proliferating B cells in latency III express a broader protein program and are more readily recognized.',reason='Retirado invisível absoluto e definido estado de repouso; imagem comparativa distingue programa0 deIII.')
set_(1792756972610,'<b>Rotavirus: mechanisms of diarrhea</b><br><b>NSP4-driven chloride secretion</b> produces {{c1::secretory}} diarrhea.<br><b>Villus injury with unabsorbed lactose</b> produces {{c1::osmotic}} diarrhea.',extra='NSP4 promotes secretion, while enterocyte injury reduces absorptive capacity and brush-border lactase. Unabsorbed lactose retains water in the lumen, so both mechanisms can coexist.',reason='Cada linha distingue mecanismo pelo evento causal, com negrito visível e nomes específicos nas lacunas.')
set_(1792786399910,'<b>siRNA silencing pathway</b><br><b>Processing long dsRNA</b>: {{c1::Dicer}} makes short duplexes.<br><b>Cleaving complementary target mRNA</b>: catalytic {{c2::Argonaute}} acts within RISC.<br>The guide strand remains available for another target.',extra='RISC is the RNA-induced silencing complex. One strand of the duplex becomes its guide; extensive guide–target pairing supports cleavage by a catalytically active Argonaute.',reason='Retirada sequência ilegível guide guide; verbos distinguem processamento de clivagem e explicam reutilização.')
set_(1792786404060,extra='Extensive guide–target pairing can support Argonaute cleavage; partial pairing commonly promotes repression and mRNA decay. A guide complex can act on successive targets. Pairing, rather than RNA-class name alone, helps determine the outcome.',reason='Verso reduzido mantendo regra funcional e ressalva sobre miRNA versus siRNA.')
set_(1792787430076,'<b>Viral injury: routes to host damage</b><br><b>Replication in the infected cell</b>: {{c1::cell destruction::c…}} or dysfunction.<br><b>Host immune response</b>: {{c1::inflammation::i…}}.<br><b>Signals affecting neighboring cells</b>: {{c1::paracrine effects::p…}}.<br><b>Persistent oncogenic change</b>: {{c1::transformation::t…}}.',extra='These mechanisms can overlap. Rotavirus NSP4 can alter neighboring enterocytes without infecting them; oncogenic viruses can instead drive long-term changes in proliferation and survival.',reason='Quarta linha passa a cobrar alvo como as outras; cada eixo é definido pelo modo de lesão, não por rótulo vago.')
set_(1793199691883,extra='Cowdry inclusions are intranuclear. Type A has an eosinophilic inclusion with a clear halo; type B gives a ground-glass nuclear appearance. The image illustrates herpesvirus-associated multinucleation and nuclear change.',reason='Comentário distingue padrões sem simplesmente repetir núcleo; retirada legenda redundante abaixo da figura.')
set_(1793784427166,'<b>Natural anti-A and anti-B</b> are predominantly {{c1::IgM}}, whereas anti-Rh produced after <b>Rh-antigen sensitization</b> is {{c1::IgG}}.',extra='IgM does not cross the placenta, whereas IgG can reach fetal red cells. Rh sensitization can follow fetomaternal bleeding or transfusion, not necessarily only a first birth. Some anti-A/anti-B, especially in group O, are IgG and can cause neonatal hemolysis.',reason='Retirada cronologia obrigatória primeiro parto/próxima gestação e doença ABO sempre leve; preservada base de isotipo e placenta.')
set_(1793784428840,extra='Immune-complex deposition activates complement and recruits inflammatory cells, injuring vessels and filtered tissues. Type III reactions can be systemic or localized, as in an Arthus reaction; circulating complexes do not make every example systemic.',reason='Corrigido absoluto sistêmico; verso liga depósito ao dano e inclui a exceção local relevante.')
set_(1793784429918,extra='The left panel shows granular deposits in lupus; the right shows linear staining in anti-GBM disease. Uneven immune-complex deposits produce a granular pattern, while antibody binding along the basement membrane produces a continuous linear pattern.',reason='Figura de dois painéis já era adequada e não expõe resposta escrita; legenda explica mecanismo do padrão observado.')
set_(1793803583523,'<b>Fluid inside a cavity: imaging contrast</b><br><b>CT neutral enteric contrast</b> may use {{c1::water}}.<br><b>T2-weighted MR hydrography</b> depicts the patient’s own {{c1::fluid}} without cavity injection.',extra='Iodinated agents and barium provide positive X-ray attenuation in appropriate enteric preparations. Neutral water in CT and bright native fluid on heavily T2-weighted MRI are different imaging strategies; native fluid is not an administered contrast agent.',reason='Retiradas rotas secundárias e falsa categoria RMfluido como contraste administrado; dois conceitos ligados pelo conteúdo da cavidade.')
set_(1793803583777,extra='Barium and iodine attenuate X-rays strongly and appear bright. Gas attenuates weakly and appears dark; water is closer to soft tissue and is used as neutral enteric contrast. The barium-filled colon below demonstrates positive luminal contrast.',image='rd56-enema-slide10.png',keep_images=False,reason='Imagem real de lúmen preenchido com bário ilustra atenuação, em vez de foto do elemento químico.')
set_(1793803584848,'The <b>upper GI series</b> follows <b>swallowed contrast</b> to the {{c1::duodenum}}, while a <b>rectal barium enema</b> outlines the {{c1::colon}}.',extra='The entry route determines which lumen fills. Fluoroscopy follows transit through the upper gut after swallowing; retrograde rectal filling outlines the colon and its mucosal contours.',reason='Negrito identifica via e exame; verso explica o que a via permite observar sem conduta clínica avançada.')
set_(1793803589750,reason='Conduta pericontraste com metformina é Step2-only e foi explicitamente retirada por Davi; suspender sem apagar ou alterar histórico.')
P[str(1793803589750)]['suspender']=True
set_(1793803591426,'<b>IgE-mediated anaphylaxis</b> activates mast cells through {{c1::IgE}}, whereas <b>non-IgE-mediated activation</b> occurs {{c1::without IgE}}.',extra='IgE-mediated activation follows cross-linking of receptor-bound IgE. Other pathways can activate mast cells without IgE, including direct receptor activation or complement-related mechanisms. Similar clinical manifestations do not prove the same molecular trigger.',image='im64-mediadores-slide70.png',keep_images=False,reason='Termo anafilactoide substituído por mecanismo; retirada equivalência de conduta Step2 e afirmação de ativação sempre direta.')
json.dump(P,open(C/'propostas.json','w'),ensure_ascii=False,indent=1)
print(len(P),'propostas preparadas; ainda sem escrita no Anki')
